"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import type { SlashItem } from "./rich-text-editor-slash"

type RichTextEditorProps = {
  content?: string
  onChange?: (html: string) => void
  placeholder?: string
  className?: string
  /** Id of the editing area. A `<label htmlFor>` cannot name it (it is not a form control): use `aria-labelledby`. */
  id?: string
  /** Accessible name of the editing area when there is no visible label. */
  "aria-label"?: string
  /** Id of the element that names the editing area, such as a visible label. */
  "aria-labelledby"?: string
  /** Id of the element that describes the editing area, such as a helper line. */
  "aria-describedby"?: string
  /**
   * Typing "/" at the start of a line or after a space opens a block menu at the caret: arrow keys pick, Enter or Tab
   * inserts, Escape closes, typing filters. `true` shows the default blocks (headings, lists, task, quote, divider,
   * code); pass your own list to replace them, e.g. `[...richTextEditorSlashItems, myItem]`. Off by default.
   */
  slashMenu?: boolean | SlashItem[]
}

function RichTextEditorSkeleton({ placeholder, className }: Pick<RichTextEditorProps, "placeholder" | "className">) {
  return (
    <div className={cn("flex flex-col rounded-md border border-input bg-card", className)}>
      <div className="h-[38px] border-b border-border" />
      <div className="min-h-32 p-3 text-sm text-text-tertiary">{placeholder}</div>
    </div>
  )
}

// TipTap is a regular dependency (bundlers resolve this import at build time,
// so it cannot be optional), but it is only imported inside the lazy chunk:
// apps that never render the editor never download it.
const RichTextEditorInner = React.lazy(() => import("./rich-text-editor-inner"))

function RichTextEditor(props: RichTextEditorProps) {
  const [mounted, setMounted] = React.useState(false)
  React.useEffect(() => setMounted(true), [])
  const fallback = <RichTextEditorSkeleton placeholder={props.placeholder ?? "Write something..."} className={props.className} />
  if (!mounted) return fallback
  return (
    <React.Suspense fallback={fallback}>
      <RichTextEditorInner {...props} />
    </React.Suspense>
  )
}

export { RichTextEditor, RichTextEditorSkeleton }
export { richTextEditorSlashItems } from "./rich-text-editor-slash"
export type { RichTextEditorProps }
export type { SlashItem } from "./rich-text-editor-slash"

"use client"

import * as React from "react"
import type { Editor } from "@tiptap/react"
import { Icon } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"

/** One entry of the RichTextEditor's "/" menu. `run` gets the editor after the "/query" text was removed. */
export type SlashItem = {
  id: string
  label: string
  icon?: React.ReactNode
  /** Extra words the filter matches, e.g. ["h1", "title"] for Heading 1. */
  keywords?: string[]
  run: (editor: Editor) => void
}

/** The default blocks of the "/" menu: headings, lists, task, quote, divider and code. Spread them to add your own. */
export const richTextEditorSlashItems: SlashItem[] = [
  { id: "heading-1", label: "Heading 1", icon: <Icon name="formatHeading1" />, keywords: ["h1", "title", "large"], run: (e) => e.chain().focus().toggleHeading({ level: 1 }).run() },
  { id: "heading-2", label: "Heading 2", icon: <Icon name="formatHeading2" />, keywords: ["h2", "subtitle", "section"], run: (e) => e.chain().focus().toggleHeading({ level: 2 }).run() },
  { id: "bulleted-list", label: "Bulleted list", icon: <Icon name="formatBulletList" />, keywords: ["ul", "bullet", "unordered"], run: (e) => e.chain().focus().toggleBulletList().run() },
  { id: "numbered-list", label: "Numbered list", icon: <Icon name="formatNumberedList" />, keywords: ["ol", "ordered", "1."], run: (e) => e.chain().focus().toggleOrderedList().run() },
  { id: "task", label: "Task", icon: <Icon name="formatTaskList" />, keywords: ["todo", "checkbox", "checklist"], run: (e) => e.chain().focus().toggleList("taskList", "taskItem").run() },
  { id: "quote", label: "Quote", icon: <Icon name="formatQuote" />, keywords: ["blockquote", "citation"], run: (e) => e.chain().focus().toggleBlockquote().run() },
  { id: "divider", label: "Divider", icon: <Icon name="formatDivider" />, keywords: ["hr", "line", "separator", "rule"], run: (e) => e.chain().focus().setHorizontalRule().run() },
  { id: "code", label: "Code", icon: <Icon name="formatCode" />, keywords: ["codeblock", "snippet", "pre"], run: (e) => e.chain().focus().toggleCodeBlock().run() },
]

/** The items that match the text typed after "/": label or keyword, ignoring case. */
export function filterSlashItems(items: SlashItem[], query: string) {
  const q = query.trim().toLowerCase()
  if (!q) return items
  return items.filter((item) => item.label.toLowerCase().includes(q) || item.keywords?.some((k) => k.toLowerCase().includes(q)))
}

/** The listbox under the caret; the editing area keeps the focus and points at the active option. */
export function SlashMenuList({
  id,
  items,
  active,
  position,
  onPick,
  onHover,
}: {
  id: string
  items: SlashItem[]
  active: number
  position: { top: number; left: number }
  onPick: (item: SlashItem) => void
  onHover: (index: number) => void
}) {
  const listRef = React.useRef<HTMLDivElement>(null)
  React.useEffect(() => {
    const option = listRef.current?.querySelector<HTMLElement>(`[data-index="${active}"]`)
    option?.scrollIntoView?.({ block: "nearest" })
  }, [active])
  return (
    // No entrance motion: the menu is keyboard-driven and opens many times a day (M11).
    <div
      ref={listRef}
      id={id}
      role="listbox"
      aria-label="Blocks"
      data-slot="rich-text-editor-slash-menu"
      className="absolute z-50 max-h-72 w-60 overflow-y-auto rounded-lg bg-popover p-1 text-popover-foreground shadow-md ring-1 ring-foreground/10"
      style={{ top: position.top, left: position.left }}
    >
      {items.map((item, index) => (
        <div
          key={item.id}
          id={`${id}-${item.id}`}
          role="option"
          aria-selected={index === active}
          data-index={index}
          data-slot="rich-text-editor-slash-item"
          // keep the caret in the editor while clicking
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => onPick(item)}
          onMouseMove={() => index !== active && onHover(index)}
          className={cn(
            "flex h-8 cursor-default items-center gap-2 rounded-md px-2 text-label-sm font-medium text-foreground select-none",
            "aria-selected:bg-bg-page active:bg-bg-subtle [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-text-secondary"
          )}
        >
          {item.icon && (
            <span aria-hidden="true" className="flex shrink-0">
              {item.icon}
            </span>
          )}
          <span className="truncate">{item.label}</span>
        </div>
      ))}
    </div>
  )
}

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

"use client"

import * as React from "react"
import { useEditor, EditorContent, type Editor } from "@tiptap/react"
import StarterKit from "@tiptap/starter-kit"
import Placeholder from "@tiptap/extension-placeholder"
import { Icon } from "@/components/ui/icon-provider"
import { Separator } from "@/components/ui/separator"
import { cn } from "@/lib/utils"
import { RichTextEditorSkeleton, type RichTextEditorProps } from "./rich-text-editor"
import { filterSlashItems, richTextEditorSlashItems, SlashMenuList, type SlashItem } from "./rich-text-editor-slash"
import { TaskItem, TaskList } from "./rich-text-editor-tasks"

function RichTextEditorToolbarButton({
  active,
  disabled,
  onClick,
  label,
  children,
}: {
  active?: boolean
  disabled?: boolean
  onClick: () => void
  /** Accessible name — the buttons only show an icon. */
  label: string
  children: React.ReactNode
}) {
  return (
    <button
      aria-label={label}
      aria-pressed={active}
      title={label}
      type="button"
      disabled={disabled}
      onClick={onClick}
      className={cn(
        "flex size-7 items-center justify-center rounded-md text-text-secondary outline-none transition-colors duration-fast ease-entrance hover:bg-bg-page active:bg-bg-subtle focus-ring disabled:pointer-events-none disabled:opacity-40 [&_svg]:size-4",
        active && "bg-bg-subtle text-foreground hover:bg-bg-subtle"
      )}
    >
      {children}
    </button>
  )
}

function RichTextEditorToolbar({ editor }: { editor: Editor }) {
  return (
    <div className="flex items-center gap-0.5 border-b border-border p-1.5">
      <RichTextEditorToolbarButton
        label="Bold"
        active={editor.isActive("bold")}
        onClick={() => editor.chain().focus().toggleBold().run()}
      >
        <Icon name="formatBold" />
      </RichTextEditorToolbarButton>
      <RichTextEditorToolbarButton
        label="Italic"
        active={editor.isActive("italic")}
        onClick={() => editor.chain().focus().toggleItalic().run()}
      >
        <Icon name="formatItalic" />
      </RichTextEditorToolbarButton>
      <RichTextEditorToolbarButton
        label="Underline"
        active={editor.isActive("underline")}
        onClick={() => editor.chain().focus().toggleUnderline().run()}
      >
        <Icon name="formatUnderline" />
      </RichTextEditorToolbarButton>
      <Separator orientation="vertical" className="mx-1 h-5 data-vertical:self-center" />
      <RichTextEditorToolbarButton
        label="Bulleted list"
        active={editor.isActive("bulletList")}
        onClick={() => editor.chain().focus().toggleBulletList().run()}
      >
        <Icon name="formatBulletList" />
      </RichTextEditorToolbarButton>
      <RichTextEditorToolbarButton
        label="Numbered list"
        active={editor.isActive("orderedList")}
        onClick={() => editor.chain().focus().toggleOrderedList().run()}
      >
        <Icon name="formatNumberedList" />
      </RichTextEditorToolbarButton>
      <Separator orientation="vertical" className="mx-1 h-5 data-vertical:self-center" />
      <RichTextEditorToolbarButton
        label="Link"
        active={editor.isActive("link")}
        onClick={() => {
          const url = window.prompt("URL")
          if (url === null) return // Cancel keeps the link as it is.
          if (url) editor.chain().focus().setLink({ href: url }).run()
          else editor.chain().focus().unsetLink().run()
        }}
      >
        <Icon name="formatLink" />
      </RichTextEditorToolbarButton>
    </div>
  )
}

const EDITOR_CLASS =
  "min-h-32 p-3 text-sm text-foreground outline-none [&_a]:text-text-link [&_a]:underline [&_ul]:list-disc [&_ul]:ps-5 [&_ol]:list-decimal [&_ol]:ps-5 [&_p.is-editor-empty:first-child::before]:text-text-tertiary [&_p.is-editor-empty:first-child::before]:content-[attr(data-placeholder)] [&_p.is-editor-empty:first-child::before]:float-left [&_p.is-editor-empty:first-child::before]:pointer-events-none [&_p.is-editor-empty:first-child::before]:h-0"

// The blocks the "/" menu inserts; only added with slashMenu, so editors without it render exactly as before.
const BLOCK_CLASS =
  "[&>*+*]:mt-2 [&_h1]:text-xl [&_h1]:font-semibold [&_h2]:text-lg [&_h2]:font-semibold [&_blockquote]:border-s-2 [&_blockquote]:border-border-control [&_blockquote]:ps-3 [&_blockquote]:text-text-secondary [&_hr]:my-3 [&_hr]:border-border [&_pre]:rounded-md [&_pre]:bg-bg-page [&_pre]:p-3 [&_pre]:font-mono [&_pre]:text-xs [&_code]:font-mono " +
  "[&_ul[data-type=taskList]]:list-none [&_ul[data-type=taskList]]:ps-0 [&_li[data-type=taskItem]]:flex [&_li[data-type=taskItem]]:items-start [&_li[data-type=taskItem]]:gap-2 [&_li[data-type=taskItem]>label]:flex [&_li[data-type=taskItem]>label]:h-5 [&_li[data-type=taskItem]>label]:items-center [&_li[data-type=taskItem]>div]:min-w-0 [&_li[data-type=taskItem]>div]:flex-1 [&_li[data-checked=true]>div]:text-text-secondary [&_li[data-checked=true]>div]:line-through [&_input[type=checkbox]]:size-4 [&_input[type=checkbox]]:accent-(--primary)"

type SlashState = { from: number; query: string }

// stands in for images and other leaf nodes in the text before the caret (a "/" right after one does not open the menu)
const LEAF_TEXT = String.fromCharCode(0xfffc)

// Loaded lazily by rich-text-editor.tsx so @tiptap/* stays an optional peer:
// this file is the only one that imports it, and tsup splits it into its own chunk.
function RichTextEditorInner({
  content,
  onChange,
  placeholder = "Write something...",
  className,
  id,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  "aria-describedby": ariaDescribedBy,
  slashMenu,
}: RichTextEditorProps) {
  const slashItems = React.useMemo<SlashItem[] | null>(
    () =>
      slashMenu === true
        ? richTextEditorSlashItems
        : Array.isArray(slashMenu)
          ? slashMenu
          : null,
    [slashMenu],
  )
  const slashOn = slashItems !== null
  const menuId = React.useId()
  const frameRef = React.useRef<HTMLDivElement>(null)
  const [slash, setSlash] = React.useState<SlashState | null>(null)
  const [active, setActive] = React.useState(0)
  const [position, setPosition] = React.useState({ top: 40, left: 12 })
  // Escape closes the menu for this "/" until the caret leaves it.
  const dismissedAt = React.useRef<number | null>(null)
  const keyHandler = React.useRef<(event: KeyboardEvent) => boolean>(
    () => false,
  )
  const syncRef = React.useRef<(editor: Editor) => void>(() => {})

  const matches = React.useMemo(
    () =>
      slash && slashItems ? filterSlashItems(slashItems, slash.query) : [],
    [slash, slashItems],
  )
  const open = slash !== null && matches.length > 0
  // a new "/" or a new filter starts at the first block
  React.useEffect(() => setActive(0), [slash?.from, slash?.query])

  syncRef.current = (ed: Editor) => {
    if (!slashOn) return
    const { selection } = ed.state
    const $from = selection.$from
    const before =
      selection.empty && $from.parent.type.name !== "codeBlock"
        ? $from.parent.textBetween(0, $from.parentOffset, undefined, LEAF_TEXT)
        : ""
    const match = /(?:^|\s)\/([^\s/]*)$/.exec(before)
    if (!match) {
      dismissedAt.current = null
      setSlash(null)
      return
    }
    const from = $from.pos - match[1].length - 1
    if (dismissedAt.current === from) return setSlash(null)
    setSlash((prev) => (prev?.from === from && prev.query === match[1] ? prev : { from, query: match[1] }))
  }

  const editor = useEditor({
    immediatelyRender: false,
    // TipTap 3 no longer re-renders on every transaction by default; the
    // toolbar reads isActive() at render, so without this it goes stale.
    shouldRerenderOnTransaction: true,
    extensions: [
      StarterKit.configure({
        link: { openOnClick: false, autolink: true },
      }),
      Placeholder.configure({ placeholder }),
      ...(slashOn ? [TaskList, TaskItem] : []),
    ],
    content,
    onUpdate: ({ editor }) => {
      onChange?.(editor.getHTML())
      syncRef.current(editor)
    },
    onSelectionUpdate: ({ editor }) => syncRef.current(editor),
    onBlur: () => setSlash(null),
    editorProps: {
      handleKeyDown: (_view, event) => keyHandler.current(event),
      attributes: {
        // The editing area is a multi-line text box: without a role and a name a screen reader announces only "edit".
        role: "textbox",
        "aria-multiline": "true",
        ...(id ? { id } : {}),
        ...(ariaLabel ? { "aria-label": ariaLabel } : {}),
        ...(ariaLabelledBy ? { "aria-labelledby": ariaLabelledBy } : {}),
        ...(ariaDescribedBy ? { "aria-describedby": ariaDescribedBy } : {}),
        class: slashOn ? `${EDITOR_CLASS} ${BLOCK_CLASS}` : EDITOR_CLASS,
      },
    },
  })

  const pick = React.useCallback(
    (item: SlashItem) => {
      if (!editor || !slash) return
      editor
        .chain()
        .focus()
        .deleteRange({ from: slash.from, to: editor.state.selection.from })
        .run()
      setSlash(null)
      item.run(editor)
    },
    [editor, slash],
  )

  keyHandler.current = (event) => {
    if (!open) return false
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      const step = event.key === "ArrowDown" ? 1 : -1
      setActive((i) => (i + step + matches.length) % matches.length)
      return true
    }
    if (event.key === "Enter" || event.key === "Tab") {
      const item = matches[Math.min(active, matches.length - 1)]
      if (item) pick(item)
      return true
    }
    if (event.key === "Escape") {
      dismissedAt.current = slash?.from ?? null
      setSlash(null)
      return true
    }
    return false
  }

  // The menu sits under the "/" (falls back to the top-left corner where layout is not measured).
  React.useLayoutEffect(() => {
    if (!open || !editor || !frameRef.current) return
    try {
      const caret = editor.view.coordsAtPos(slash.from)
      const frame = frameRef.current.getBoundingClientRect()
      const left = Math.max(
        0,
        Math.min(caret.left - frame.left, frame.width - 240),
      )
      setPosition({
        top: Math.round(caret.bottom - frame.top + 4),
        left: Math.round(left),
      })
    } catch {
      setPosition({ top: 40, left: 12 })
    }
  }, [open, editor, slash?.from])

  // Combobox pattern on the editing area: it keeps the focus and points at the active option.
  const activeId = open
    ? `${menuId}-${matches[Math.min(active, matches.length - 1)]?.id}`
    : null
  React.useEffect(() => {
    const dom = editor?.view.dom
    if (!dom || !slashOn) return
    if (activeId) {
      dom.setAttribute("aria-controls", menuId)
      dom.setAttribute("aria-activedescendant", activeId)
    } else {
      dom.removeAttribute("aria-controls")
      dom.removeAttribute("aria-activedescendant")
    }
  }, [editor, activeId, menuId, slashOn])

  if (!editor)
    return (
      <RichTextEditorSkeleton placeholder={placeholder} className={className} />
    )

  return (
    <div
      ref={frameRef}
      className={cn(
        slashOn && "relative",
        "flex flex-col rounded-md border border-input bg-card has-[[contenteditable]:focus-visible]:focus-ring-on",
        className,
      )}
    >
      <RichTextEditorToolbar editor={editor} />
      <EditorContent editor={editor} />
      {open && (
        <SlashMenuList
          id={menuId}
          items={matches}
          active={Math.min(active, matches.length - 1)}
          position={position}
          onPick={pick}
          onHover={setActive}
        />
      )}
      {slashOn && (
        <div className="sr-only" aria-live="polite" aria-atomic="true">
          {open
            ? `${matches.length} ${matches.length === 1 ? "block" : "blocks"}`
            : ""}
        </div>
      )}
    </div>
  )
}

export default RichTextEditorInner

// Task list nodes for the RichTextEditor's "/" menu. Built on the Tiptap core that @tiptap/react re-exports, so the
// editor needs no extra package. Loaded only by rich-text-editor-inner.tsx (the lazy chunk).
import { mergeAttributes, Node, wrappingInputRule } from "@tiptap/react"

export const TaskList = Node.create({
  name: "taskList",
  group: "block list",
  content: "taskItem+",
  parseHTML() {
    return [{ tag: 'ul[data-type="taskList"]', priority: 51 }]
  },
  renderHTML({ HTMLAttributes }) {
    return ["ul", mergeAttributes(HTMLAttributes, { "data-type": "taskList" }), 0]
  },
})

export const TaskItem = Node.create({
  name: "taskItem",
  content: "paragraph+",
  defining: true,
  addAttributes() {
    return {
      checked: {
        default: false,
        keepOnSplit: false,
        parseHTML: (element: HTMLElement) => {
          const value = element.getAttribute("data-checked")
          return value === "" || value === "true"
        },
        renderHTML: (attributes: { checked?: boolean }) => ({ "data-checked": attributes.checked ? "true" : "false" }),
      },
    }
  },
  parseHTML() {
    return [{ tag: 'li[data-type="taskItem"]', priority: 51, contentElement: (el: HTMLElement) => el.querySelector("div") ?? el }]
  },
  renderHTML({ node, HTMLAttributes }) {
    return [
      "li",
      mergeAttributes(HTMLAttributes, { "data-type": "taskItem" }),
      ["label", { contenteditable: "false" }, ["input", { type: "checkbox", checked: node.attrs.checked ? "checked" : null }]],
      ["div", 0],
    ]
  },
  addKeyboardShortcuts() {
    return {
      Enter: () => this.editor.commands.splitListItem(this.name),
      "Shift-Tab": () => this.editor.commands.liftListItem(this.name),
    }
  },
  addNodeView() {
    return ({ node, HTMLAttributes, getPos, editor }) => {
      const item = document.createElement("li")
      const label = document.createElement("label")
      const checkbox = document.createElement("input")
      const content = document.createElement("div")
      const sync = (n: typeof node) => {
        item.dataset.checked = n.attrs.checked ? "true" : "false"
        checkbox.checked = Boolean(n.attrs.checked)
        checkbox.setAttribute("aria-label", `${n.attrs.checked ? "Done" : "To do"}: ${n.textContent || "empty task"}`)
      }
      for (const [key, value] of Object.entries(HTMLAttributes)) if (value != null) item.setAttribute(key, String(value))
      item.dataset.type = "taskItem"
      label.contentEditable = "false"
      checkbox.type = "checkbox"
      checkbox.addEventListener("mousedown", (event) => event.preventDefault())
      checkbox.addEventListener("change", () => {
        if (!editor.isEditable || typeof getPos !== "function") {
          checkbox.checked = !checkbox.checked
          return
        }
        editor
          .chain()
          .focus(undefined, { scrollIntoView: false })
          .command(({ tr }) => {
            const pos = getPos()
            if (typeof pos !== "number") return false
            tr.setNodeMarkup(pos, undefined, { ...tr.doc.nodeAt(pos)?.attrs, checked: checkbox.checked })
            return true
          })
          .run()
      })
      sync(node)
      label.append(checkbox)
      item.append(label, content)
      return {
        dom: item,
        contentDOM: content,
        update: (updated) => {
          if (updated.type !== node.type) return false
          sync(updated)
          return true
        },
      }
    }
  },
  addInputRules() {
    return [
      wrappingInputRule({
        find: /^\s*(\[([( |x])?\])\s$/,
        type: this.type,
        getAttributes: (match) => ({ checked: match[match.length - 1] === "x" }),
      }),
    ]
  },
})

"use client"

import { Separator as SeparatorPrimitive } from "@base-ui/react/separator"
import { cn } from "@/lib/utils"

function Separator({
  className,
  orientation = "horizontal",
  dashed = false,
  ...props
}: SeparatorPrimitive.Props & { dashed?: boolean }) {
  return (
    <SeparatorPrimitive
      data-slot="separator"
      orientation={orientation}
      className={cn(
        dashed
          ? "shrink-0 border-border data-horizontal:h-0 data-horizontal:w-full data-horizontal:border-t data-vertical:h-full data-vertical:w-0 data-vertical:self-stretch data-vertical:border-l border-dashed"
          : "shrink-0 bg-border data-horizontal:h-px data-horizontal:w-full data-vertical:w-px data-vertical:self-stretch",
        className
      )}
      {...props}
    />
  )
}

export { Separator }
